"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { Trash2, Plus, Layout } from "lucide-react";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);
  const [newColumn, setNewColumn] = useState("");

  useEffect(() => {
    fetch("/api/admin/stats").then(res => res.json()).then(setData);
  }, []);

  // KULLANICI SİLME FONKSİYONU
  const deleteUser = async (id: string) => {
    if (!confirm("Bu kullanıcıyı ve tüm verilerini (görevler, takvim vb.) silmek istediğinize emin misiniz?")) return;
    
    const res = await fetch(`/api/admin/users/${id}`, { method: "DELETE" });
    if (res.ok) {
      setData({ ...data, stats: data.stats.filter((u: any) => u.id !== id) });
      alert("Kullanıcı başarıyla imha edildi.");
    }
  };

  // YENİ SÜTUN (REVIEW, RETRO VB.) EKLEME
  const addColumn = async () => {
    if (!newColumn) return;
    const res = await fetch("/api/admin/columns", {
      method: "POST",
      body: JSON.stringify({ name: newColumn }),
    });
    if (res.ok) {
      alert(`${newColumn} aşaması tüm tahtalara eklendi!`);
      setNewColumn("");
    }
  };

  if (!data) return <div className="p-10 text-teal-400 animate-pulse font-black">SİSTEM YÜKLENİYOR...</div>;

  return (
    <div className="space-y-10 pb-20">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-4xl font-black text-fuchsia-500 uppercase italic">Admin Konsolu</h1>
          <p className="text-teal-400/50 text-xs tracking-widest uppercase">Sistem ve Kullanıcı Yönetimi</p>
        </div>
      </header>

      {/* 1. SÜRECİ YÖNET (REVIEW, RETRO EKLE) */}
      <div className="bg-[#0E153A] border border-fuchsia-500/20 p-8 rounded-[2.5rem] shadow-2xl">
        <div className="flex items-center gap-3 mb-6">
          <Layout className="text-fuchsia-400" />
          <h2 className="text-xl font-bold text-white uppercase italic">İş Akışını Düzenle</h2>
        </div>
        <div className="flex gap-4">
          <input 
            value={newColumn}
            onChange={(e) => setNewColumn(e.target.value)}
            placeholder="Örn: Review, Testing, Retro..."
            className="flex-1 bg-black/40 border border-teal-400/20 p-4 rounded-2xl text-white focus:outline-none focus:border-fuchsia-500 transition-all"
          />
          <button 
            onClick={addColumn}
            className="bg-fuchsia-600 hover:bg-fuchsia-500 px-8 rounded-2xl text-white font-black uppercase flex items-center gap-2 transition-all shadow-lg shadow-fuchsia-500/20"
          >
            <Plus size={20} /> Ekle
          </button>
        </div>
      </div>

      {/* 2. KULLANICI LİSTESİ VE SİLME */}
      <div className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2.5rem] overflow-hidden">
        <div className="p-6 bg-teal-400/5 border-b border-teal-400/10 text-teal-400 font-bold uppercase text-xs tracking-widest">
          Aktif Kullanıcılar ve Performans
        </div>
        <div className="divide-y divide-white/5">
          {data.stats.map((user: any) => (
            <div key={user.id} className="p-6 flex items-center justify-between hover:bg-white/5 transition-all group">
              <div className="flex-1">
                <h3 className="text-white font-bold">{user.name || "İsimsiz"}</h3>
                <p className="text-[10px] text-teal-500/50 uppercase">{user.email}</p>
                {/* Performans Barı */}
                <div className="w-48 h-1.5 bg-black/40 rounded-full mt-2 overflow-hidden">
                  <div className="h-full bg-fuchsia-500" style={{ width: `${user.percentage}%` }} />
                </div>
              </div>
              
              <div className="flex items-center gap-6">
                <span className="text-fuchsia-400 font-black italic">{user.percentage}%</span>
                <button 
                  onClick={() => deleteUser(user.id)}
                  className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all transform group-hover:scale-110"
                  title="Kullanıcıyı Sil"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}